      <span class="stepper"><button type="button" data-action="patrouille" data-c="${j}" data-d="-1" aria-label="Une patrouille de moins à ${A}" ${q<=0?"disabled":""}>−</button><span class="n">${q}</span><button type="button" data-action="patrouille" data-c="${j}" data-d="1" aria-label="Une patrouille de plus à ${A}" ${l<=q?"disabled":""}>+</button></span>
